cd /private/tmp/claude-501/-Users-guillaumeloulier-PhpstormProjects-oss-elephc--claude-worktrees-streams-csv-signature/c8dbe38f-1f79-484f-9b83-62bacab9ca56/scratchpad/probe2 && python3 - <<'PY'
p='prelude_body.php'
s=open(p).read()
s=s.replace("function __elephc_scanf_unsigned(string $digits, int $sign, int $base): int|string","function __elephc_scanf_unsigned(string $digits, int $sign): int|string")
s=s.replace("return [$si, true, __elephc_scanf_unsigned($digits, $sign, $base)];","return [$si, true, __elephc_scanf_unsigned($digits, $sign)];")
open(p,'w').write(s)

body = s.split('<?php',1)[1]
corpus = open('diff.php').read()
import re
subj = re.search(r'\$subjects = \[(.*?)\n\];', corpus, re.S).group(0)
fmts = re.search(r'\$formats = \[(.*?)\n\];', corpus, re.S).group(0)
drv = "<?php\n" + body + "\n" + subj + "\n" + fmts + '''
function render(mixed $v): string
{
    if (is_int($v)) { return "i:" . $v; }
    if (is_float($v)) { return "f:" . var_export($v, true); }
    if (is_string($v)) { return "s:" . var_export($v, true); }
    if ($v === null) { return "NULL"; }
    return "?";
}
foreach ($subjects as $s) {
    foreach ($formats as $f) {
        $line = var_export($s, true) . " | " . var_export($f, true) . " => ";
        try {
            $r = __elephc_sscanf($s, $f);
            if ($r === null) {
                $line = $line . "NULL";
            } else {
                $parts = [];
                foreach ($r as $v) { $parts[] = render($v); }
                $line = $line . "[" . implode(",", $parts) . "]";
            }
            $line = $line . " c=" . __ElephcScanfState::$count . " n=" . __ElephcScanfState::$specs;
        } catch (\\ValueError $e) {
            $line = $line . "ValueError: " . $e->getMessage();
        }
        echo $line, "\\n";
    }
}
'''
open('full2.php','w').write(drv)
PY
